head.script:
// 모바일 팝업 생성 함수
scwin.createPopupLayer = function () {
    if (document.getElementById('mobileAlertPopup')) return;

    var popupHtml = `
        <div id="mobileAlertPopup" style="position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.5); z-index: 99999; display: none; align-items: center; justify-content: center; font-family: 'Pretendard', sans-serif;">
            <div style="background: white; padding: 24px; border-radius: 16px; box-shadow: 0 10px 40px rgba(0,0,0,0.3); min-width: 280px; max-width: 90%; text-align: center; box-sizing: border-box;">
                <div id="mobilePopupMessage" style="margin-bottom: 24px; font-size: 16px; line-height: 1.5; color: #333; white-space: pre-wrap; word-break: break-word;"></div>
                <div>
                    <button id="mobilePopupConfirm" style="background: #667eea; color: white; border: none; padding: 12px 24px; margin: 0 8px; border-radius: 8px; cursor: pointer; font-size: 14px; font-weight: 500; min-width: 80px;">확인</button>
                    <button id="mobilePopupCancel" style="background: #6c757d; color: white; border: none; padding: 12px 24px; margin: 0 8px; border-radius: 8px; cursor: pointer; font-size: 14px; font-weight: 500; min-width: 80px;">취소</button>
                </div>
            </div>
        </div>
    `;
    document.body.insertAdjacentHTML('beforeend', popupHtml);
};

// 모바일 팝업 표시 함수
scwin.showPopup = function (message, isConfirm, callback) {
    console.log("showPopup 호출:", message, "콜백 존재:", !!callback);

    var popup = document.getElementById('mobileAlertPopup');
    if (!popup) {
        scwin.createPopupLayer();
        popup = document.getElementById('mobileAlertPopup');
    }

    var messageEl = document.getElementById('mobilePopupMessage');
    var confirmBtn = document.getElementById('mobilePopupConfirm');
    var cancelBtn = document.getElementById('mobilePopupCancel');

    messageEl.innerHTML = message.replace(/\\n/g, '<br>');

    // 기존 이벤트 핸들러 제거 (중복 방지)
    confirmBtn.onclick = null;
    cancelBtn.onclick = null;

    if (isConfirm) {
        cancelBtn.style.display = 'inline-block';

        confirmBtn.onclick = function (e) {
            console.log("확인 버튼 클릭됨");
            e.preventDefault();
            e.stopPropagation();

            popup.style.display = 'none';

            // 안전한 콜백 실행 (지연 처리)
            if (callback) {
                setTimeout(function() {
                    console.log("확인 콜백 실행");
                    callback(true);
                }, 100); // 팝업이 완전히 숨겨진 후 실행
            }
        };

        cancelBtn.onclick = function (e) {
            console.log("취소 버튼 클릭됨");
            e.preventDefault();
            e.stopPropagation();

            popup.style.display = 'none';

            if (callback) {
                setTimeout(function() {
                    console.log("취소 콜백 실행");
                    callback(false);
                }, 100);
            }
        };

    } else {
        cancelBtn.style.display = 'none';

        confirmBtn.onclick = function (e) {
            console.log("확인 버튼 클릭됨 (단일)");
            e.preventDefault();
            e.stopPropagation();

            popup.style.display = 'none';

            // 핵심: 콜백을 지연 실행
            if (callback) {
                setTimeout(function() {
                    console.log("콜백 실행 중...");
                    try {
                        callback();
                        console.log("콜백 실행 완료");
                    } catch (error) {
                        console.error("콜백 실행 오류:", error);
                    }
                }, 150); // 충분한 지연 시간
            }
        };
    }

    popup.style.display = 'flex';

    // 포커스 설정 (키보드 접근성)
    setTimeout(function() {
        if (confirmBtn) {
            confirmBtn.focus();
        }
    }, 50);
};

// JWT 파싱 함수
scwin.parseJwt = function (token) {
    try {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(function (c) {
            return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        return JSON.parse(jsonPayload);
    } catch (e) {
        console.error("JWT 파싱 오류:", e);
        return null;
    }
};

scwin.onpageload = function () {
    // 모바일 팝업 레이어 생성
    scwin.createPopupLayer();

    // 저장된 아이디 로드
    scwin.loadSavedUserId();

    // 엔터키 이벤트 바인딩
    scwin.bindEnterKeyEvents();
};

// 저장된 아이디 로드
scwin.loadSavedUserId = function () {
    try {
        var savedUserId = localStorage.getItem("savedUserId");
        if (savedUserId) {
            inp_userId.setValue(savedUserId);
            chk_remember.setChecked(true);
        }
    } catch (e) {
        console.warn("로컬 스토리지 접근 실패:", e);
    }
};

scwin.bindEnterKeyEvents = function () {
    inp_userId.bind("keypress", function (e) {
        if (e.keyCode === 13) {
            e.preventDefault();
            inp_password.focus();
        }
    });

    inp_password.bind("keypress", function (e) {
        if (e.keyCode === 13) {
            e.preventDefault();
            scwin.login();
        }
    });
};

// 로그인 함수
scwin.login = function () {
    console.log("=== 로그인 시작 ===");

    var userId = inp_userId.getValue();
    var password = inp_password.getValue();

    if (!scwin.validateLogin(userId, password)) {
        return;
    }

    dma_login.set("email", userId);
    dma_login.set("password", password);
    dma_login.set("subDomain", "admin");

    scwin.setLoginButtonState(true);


    try {
        $p.executeSubmission("login");
    } catch (e) {
        scwin.setLoginButtonState(false);
        scwin.showPopup("로그인 요청 중 오류가 발생했습니다.", false);
    }
};

// 입력값 검증
scwin.validateLogin = function (userId, password) {
    if (!userId || userId.trim() === "") {
        scwin.showPopup("아이디를 입력해주세요.", false, function () {
            inp_userId.focus();
        });
        return false;
    }

    if (!password || password.trim() === "") {
        scwin.showPopup("비밀번호를 입력해주세요.", false, function () {
            inp_password.focus();
        });
        return false;
    }

    if (userId.length < 3) {
        scwin.showPopup("아이디는 3글자 이상 입력해주세요.", false, function () {
            inp_userId.focus();
        });
        return false;
    }

    return true;
};

// 로그인 버튼 상태 변경
scwin.setLoginButtonState = function (isLoading) {
    if (isLoading) {
        btn_login.setDisabled(true);
        btn_login.setLabel("로그인 중...");
    } else {
        btn_login.setDisabled(false);
        btn_login.setLabel("로그인");
    }
};

// 로그인 성공 처리
scwin.onLoginSuccess = function () {
    scwin.setLoginButtonState(false);

    var userId = inp_userId.getValue();
    var rememberMe = chk_remember.getChecked();

    try {
        // 아이디 저장 처리
        if (rememberMe) {
            localStorage.setItem("savedUserId", userId);
        } else {
            localStorage.removeItem("savedUserId");
        }

        sessionStorage.setItem("loggedInUser", userId);

    } catch (e) {
    }

    scwin.showPopup("로그인되었습니다.", false, function () {
        scwin.redirectToMobileDashboard();
    });
};

// 로그인 실패 처리
scwin.onLoginFailure = function () {
    scwin.setLoginButtonState(false);

    scwin.showPopup("아이디 또는 비밀번호가 올바르지 않습니다.", false, function () {
        inp_password.setValue("");
        inp_password.focus();
    });
};

// 모바일 대시보드로 리다이렉트
scwin.redirectToMobileDashboard = function () {
    try {
        // 모바일 대시보드로 이동
        // location.href = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/mobile_tenant_dashboard.xml";
    } catch (e) {
        console.log("모바일 대시보드 이동 처리");
    }
};

// 비밀번호 보기/숨기기 토글
scwin.togglePasswordVisibility = function () {
    if (inp_password.getInputType() === "password") {
        inp_password.setInputType("text");
        btn_password_toggle.setText("숨기기");
    } else {
        inp_password.setInputType("password");
        btn_password_toggle.setText("보기");
    }
};

// 로그인 응답 처리
scwin.login_submitdone = function (e) {
    console.log("=== 로그인 응답 수신 ===");

    var responseData = e.responseJSON;
    if (!responseData) {
        console.error("응답 데이터가 없습니다!");
        scwin.setLoginButtonState(false);
        scwin.showPopup("서버 응답이 없습니다. 네트워크를 확인해주세요.", false);
        return;
    }

    var elHeader = responseData.elHeader;

    if (elHeader && elHeader.resSuc === true) {
        console.log("✅ 로그인 성공!");

        var headers = {};
        try {
            headers = JSON.parse(e.responseHeadersJSON || "{}");
        } catch (err) {
            console.error("헤더 JSON 파싱 오류:", err);
        }

        var accessToken = headers.authorization;
        var refreshToken = headers["refresh-token"];

        if (accessToken) {
            sessionStorage.setItem('accessToken', accessToken);
        }
        if (refreshToken) {
            sessionStorage.setItem('refreshToken', refreshToken);
        }

        var tenantId = null;
        if (accessToken) {
            const tokenString = accessToken.startsWith('Bearer ') ? accessToken.substring(7) : accessToken;
            const tokenPayload = scwin.parseJwt(tokenString);

            if (tokenPayload && tokenPayload.tenantId) {
                tenantId = tokenPayload.tenantId;
            }
        }

        scwin.setLoginButtonState(false);

        if (tenantId) {
            var redirectUrl = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/mobile/mobile_dev_dashboard.xml&tenant=" + encodeURIComponent(tenantId);
            console.log("리다이렉트 URL 준비:", redirectUrl);

            // 팝업 사용 버전
            scwin.showPopup("로그인되었습니다!", false, function() {
                console.log("팝업 콜백에서 리다이렉트 실행");
                console.log("이동할 URL:", redirectUrl);

                try {
                    location.href = redirectUrl;
                } catch (error) {
                    console.error("리다이렉트 오류:", error);
                    // 오류 시 강제 이동
                    window.location.replace(redirectUrl);
                }
            });

        } else {
            scwin.showPopup("로그인은 성공했으나, 토큰에서 테넌트 정보를 찾을 수 없습니다.", false);
        }

    } else {
        console.log("❌ 로그인 실패");
        scwin.onLoginFailure();
    }
};
